{
  "arguments": [
    {
      "claim": "The commander exercised effective command and control over the Military Police during the period 27 December 1992 – 20 March 1993, satisfying the control element of command responsibility.",
      "reasoning": "Article 28(a) of the Rome Statute imposes liability on a military commander for crimes committed by forces under his or her effective command and control. The trial record shows that after 27 November 1992 the Military Police was subordinated to the commander through the Chiefs of Staff, establishing a chain of effective authority that persisted through the entire period of the alleged murders and cruel treatment. Customary IHL rule 153 articulates the same requirement of effective control. Consequently, the factual nexus between the commander and the Military Police meets the statutory control element.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces..."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes..."
        }
      ]
    },
    {
      "claim": "The commander either knew or, owing to the circumstances, should have known of the murders and cruel treatment of Serb detainees, satisfying the knowledge element of command responsibility.",
      "reasoning": "Article 28(a)(i) requires that the commander knew, or should have known, that the forces were committing or about to commit the crimes. The commander’s position gave him access to reports from the police station, to the presence of detainees, and to the timing of the Military Police’s deployment after 27 November 1992. Under customary rule 153, “knew, or had reason to know” is sufficient. The proximity in time between the commander’s assumption of authority and the onset of the crimes creates a presumption of constructive knowledge, which the Tribunal may draw as a matter of fact.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "that military commander or person either knew or, owing to the circumstances at the time, should have known that the forces were committing or about to commit such crimes"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes..."
        }
      ]
    },
    {
      "claim": "The commander failed to take all necessary and reasonable measures within his power to prevent or repress the murders and cruel treatment, thereby breaching his duty under Article 28(a)(ii) and Article 86(2) of Additional Protocol I.",
      "reasoning": "Article 28(a)(ii) obliges a commander to take all necessary and reasonable measures to prevent or repress the commission of crimes. The record shows that no orders were issued to protect the detainees, no investigations were launched, and the commander did not intervene to halt the Military Police’s actions. Article 86(2) of Additional Protocol I mirrors this duty, requiring superiors to act when they have information that would enable them to conclude a breach is occurring. The commander’s inaction, despite his effective authority, constitutes a failure to meet the statutory and customary standard of “all necessary and reasonable measures.”",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "that military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "The fact that a breach of the Conventions or of this Protocol was committed by a subordinate does not absolve his superiors from penal or disciplinary responsibility, as the case may be, if they knew, or had information which should have enabled them to conclude in the circumstances at the time, that he was committing or was going to commit such a breach and if they did not take all feasible measures within their power to prevent or repress the breach."
        }
      ]
    },
    {
      "claim": "The fact that the individuals who physically committed the murders were not formal members of the Military Police does not defeat the commander’s liability, because command responsibility is grounded in effective control, not formal subordination.",
      "reasoning": "Both the Rome Statute (art. 28) and customary rule 153 speak of “forces under his or her effective command and control” and of “subordinates” without requiring a formal chain‑of‑command link. The Tribunal’s findings that the Military Police was under the commander’s authority after 27 November 1992, combined with the commander’s power to direct, discipline, and supervise those forces, satisfy the effective control test. Consequently, liability attaches even if the actual perpetrators were irregular actors or volunteers operating under the Military Police’s direction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control..."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes..."
        }
      ]
    }
  ]
}

